package ro.leo.visual;
import android.content.*;import org.json.*;import java.util.*;
/** Small local playlists; original media files are never moved or deleted. */
final class MusicLists {
 static TreeMap<String,ArrayList<String[]>> read(Context c){TreeMap<String,ArrayList<String[]>> lists=new TreeMap<String,ArrayList<String[]>>(String.CASE_INSENSITIVE_ORDER);try{JSONObject root=new JSONObject(c.getSharedPreferences("music-lists",0).getString("lists","{}"));Iterator<String> keys=root.keys();while(keys.hasNext()&&lists.size()<30){String name=keys.next();JSONArray rows=root.getJSONArray(name);ArrayList<String[]> items=new ArrayList<String[]>();for(int i=0;i<rows.length()&&i<500;i++){JSONArray row=rows.getJSONArray(i);String uri=row.getString(0);if(uri.startsWith("content://")||uri.startsWith("file://"))items.add(new String[]{uri,row.getString(1)});}lists.put(name,items);}}catch(JSONException ignored){}return lists;}
 static boolean write(Context c,Map<String,ArrayList<String[]>> lists){try{JSONObject root=new JSONObject();for(Map.Entry<String,ArrayList<String[]>> e:lists.entrySet()){JSONArray rows=new JSONArray();for(String[] item:e.getValue())rows.put(new JSONArray().put(item[0]).put(item[1]));root.put(e.getKey(),rows);}return c.getSharedPreferences("music-lists",0).edit().putString("lists",root.toString()).commit();}catch(JSONException e){return false;}}
 static void saveQueue(final LeoActivity a){final PlaybackService p=PlaybackService.instance;if(p==null||p.queue.sources.isEmpty()){a.notice("Nu există o coadă de salvat");return;}final ArrayList<String[]> snapshot=new ArrayList<String[]>();for(int i=0;i<p.queue.sources.size();i++)snapshot.add(new String[]{p.queue.sources.get(i),p.queue.titles.get(i)});final android.widget.EditText name=new android.widget.EditText(a);name.setSingleLine(true);name.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(40)});new android.app.AlertDialog.Builder(a).setTitle("Salvează lista").setView(name).setPositiveButton("Salvează",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){String key=name.getText().toString().trim();TreeMap<String,ArrayList<String[]>> lists=read(a);if(key.isEmpty()||lists.containsKey(key)||lists.size()>=30){a.notice("Alege un nume nou · maximum 30 liste");return;}lists.put(key,snapshot);a.notice(write(a,lists)?"Lista a fost salvată":"Salvarea a eșuat");}}).setNegativeButton("Înapoi",null).show();}
}
